92: /**
93:  * @brief 根据全局鼠标位置和窗口矩形重新计算鼠标位置状态。
94:  * @param globalMousePos 全局鼠标位置。
95:  * @param frameRect 窗口的矩形区域。
96:  */
97: void SAPrivateFramelessCursorPosCalculator::recalculate(const QPoint& gMousePos, const QRect& frameRect)
98: {
99:     qreal dpiScale        = SAFramelessHelper::getScreenDpiScale(QApplication::widgetAt(gMousePos));
100:     int scaledBorderWidth = s_borderWidth * dpiScale;
101:     int globalMouseX      = gMousePos.x();
102:     int globalMouseY      = gMousePos.y();
103: 
104:     int frameX = frameRect.x();
105:     int frameY = frameRect.y();
106: 
107:     int frameWidth  = frameRect.width();
108:     int frameHeight = frameRect.height();
109: 
110:     mIsOnLeftEdge = (globalMouseX >= frameX && globalMouseX <= frameX + scaledBorderWidth);
111: 
112:     mIsOnRightEdge = (globalMouseX >= frameX + frameWidth - scaledBorderWidth && globalMouseX <= frameX + frameWidth);
113: 
114:     mIsOnTopEdge = (globalMouseY >= frameY && globalMouseY <= frameY + scaledBorderWidth);
115: 
116:     mIsOnBottomEdge = (globalMouseY >= frameY + frameHeight - scaledBorderWidth && globalMouseY <= frameY + frameHeight);
117: 
118:     mIsOnTopLeftEdge     = mIsOnTopEdge && mIsOnLeftEdge;
119:     mIsOnBottomLeftEdge  = mIsOnBottomEdge && mIsOnLeftEdge;
120:     mIsOnTopRightEdge    = mIsOnTopEdge && mIsOnRightEdge;
121:     mIsOnBottomRightEdge = mIsOnBottomEdge && mIsOnRightEdge;
122: 
123:     mIsOnEdges = mIsOnLeftEdge || mIsOnRightEdge || mIsOnTopEdge || mIsOnBottomEdge;
124: }
