256: void SAPrivateFramelessWidgetData::updateCursorShape(const QPoint& gMousePos)
257: {
258:     if (m_pWidget->isFullScreen() || m_pWidget->isMaximized()) {
259:         if (m_bCursorShapeChanged) {
260:             m_pWidget->unsetCursor();
261:         }
262:         return;
263:     }
264: 
265:     m_moveMousePos.recalculate(gMousePos, m_pWidget->frameGeometry());
266: 
267:     if (m_moveMousePos.mIsOnTopLeftEdge || m_moveMousePos.mIsOnBottomRightEdge) {
268:         m_pWidget->setCursor(Qt::SizeFDiagCursor);
269:         m_bCursorShapeChanged = true;
270:     } else if (m_moveMousePos.mIsOnTopRightEdge || m_moveMousePos.mIsOnBottomLeftEdge) {
271:         m_pWidget->setCursor(Qt::SizeBDiagCursor);
272:         m_bCursorShapeChanged = true;
273:     } else if (m_moveMousePos.mIsOnLeftEdge || m_moveMousePos.mIsOnRightEdge) {
274:         m_pWidget->setCursor(Qt::SizeHorCursor);
275:         m_bCursorShapeChanged = true;
276:     } else if (m_moveMousePos.mIsOnTopEdge || m_moveMousePos.mIsOnBottomEdge) {
277:         m_pWidget->setCursor(Qt::SizeVerCursor);
278:         m_bCursorShapeChanged = true;
279:     } else {
280:         if (m_bCursorShapeChanged) {
281:             m_pWidget->unsetCursor();
282:             m_bCursorShapeChanged = false;
283:         }
284:     }
285: }
