287: void SAPrivateFramelessWidgetData::resizeWidget(const QPoint& gMousePos)
288: {
289:     QRect origRect;
290:     if (d->m_bRubberBandOnResize) {
291:         origRect = m_pRubberBand->frameGeometry();
292:     } else {
293:         origRect = m_pWidget->frameGeometry();
294:     }
295: 
296:     int left   = origRect.left();
297:     int top    = origRect.top();
298:     int right  = origRect.right();
299:     int bottom = origRect.bottom();
300: 
301:     // origRect.getCoords(&left, &top, &right, &bottom);
302: 
303:     int minWidth  = m_pWidget->minimumWidth();
304:     int minHeight = m_pWidget->minimumHeight();
305: 
306:     if (m_pressedMousePos.mIsOnTopLeftEdge) {
307:         left = gMousePos.x();
308:         top  = gMousePos.y();
309:     } else if (m_pressedMousePos.mIsOnBottomLeftEdge) {
310:         left   = gMousePos.x();
311:         bottom = gMousePos.y();
312:     } else if (m_pressedMousePos.mIsOnTopRightEdge) {
313:         right = gMousePos.x();
314:         top   = gMousePos.y();
315:     } else if (m_pressedMousePos.mIsOnBottomRightEdge) {
316:         right  = gMousePos.x();
317:         bottom = gMousePos.y();
318:     } else if (m_pressedMousePos.mIsOnLeftEdge) {
319:         left = gMousePos.x();
320:     } else if (m_pressedMousePos.mIsOnRightEdge) {
321:         right = gMousePos.x();
322:     } else if (m_pressedMousePos.mIsOnTopEdge) {
323:         top = gMousePos.y();
324:     } else if (m_pressedMousePos.mIsOnBottomEdge) {
325:         bottom = gMousePos.y();
326:     }
327: 
328:     QRect newRect(QPoint(left, top), QPoint(right, bottom));
329: 
330:     if (newRect.isValid()) {
331:         if (minWidth > newRect.width()) {
332:             if (left != origRect.left()) {
333:                 newRect.setLeft(origRect.left());
334:             } else {
335:                 newRect.setRight(origRect.right());
336:             }
337:         }
338:         if (minHeight > newRect.height()) {
339:             if (top != origRect.top()) {
340:                 newRect.setTop(origRect.top());
341:             } else {
342:                 newRect.setBottom(origRect.bottom());
343:             }
344:         }
345: 
346:         if (d->m_bRubberBandOnResize) {
347:             m_pRubberBand->setGeometry(newRect);
348:         } else {
349:             m_pWidget->setGeometry(newRect);
350:         }
351:     }
352: }
