368: bool SAPrivateFramelessWidgetData::handleMousePressEvent(QMouseEvent* event)
369: {
370:     if (event->button() == Qt::LeftButton) {
371:         m_bLeftButtonPressed = true;
372: 
373:         qreal dpiScale        = SAFramelessHelper::getScreenDpiScale(m_pWidget);
374:         int scaledTitleHeight = SAPrivateFramelessCursorPosCalculator::s_titleHeight * dpiScale;
375:         // 这里要用eventPosY获取相对位置
376:         m_bLeftButtonTitlePressed = SA::compat::eventPosY(event) < scaledTitleHeight;
377: 
378:         QRect frameRect = m_pWidget->frameGeometry();
379:         auto gp         = SA::compat::eventGlobalPos(event);
380:         m_pressedMousePos.recalculate(gp, frameRect);
381: 
382:         m_ptDragPos = gp - frameRect.topLeft();
383:         if (m_pressedMousePos.mIsOnEdges) {
384:             if (m_pWidget->isMaximized()) {
385:                 // 窗口在最大化状态时，点击边界不做任何处理
386:                 return (false);
387:             }
388:             if (d->m_bRubberBandOnResize) {
389:                 m_pRubberBand->setGeometry(frameRect);
390:                 m_pRubberBand->show();
391:                 return (true);
392:             }
393:         } else if (d->m_bRubberBandOnMove && m_bLeftButtonTitlePressed) {
394:             if (m_pWidget->isMaximized()) {
395:                 // 窗口在最大化状态时，点击标题栏不做任何处理
396:                 return (false);
397:             }
398:             m_pRubberBand->setGeometry(frameRect);
399:             m_pRubberBand->show();
400:             return (true);
401:         }
402:     }
403:     return (false);
404: }
