421: bool SAPrivateFramelessWidgetData::handleMouseMoveEvent(QMouseEvent* event)
422: {
423:     QPoint globalpos = SA::compat::eventGlobalPos(event);
424:     if (m_bLeftButtonPressed) {
425:         if (d->m_bWidgetResizable && m_pressedMousePos.mIsOnEdges) {
426:             if (m_pWidget->isMaximized()) {
427:                 // 窗口在最大化状态时，点击边界不做任何处理
428:                 return (false);
429:             }
430:             resizeWidget(globalpos);
431:             return (true);
432:         } else if (d->m_bWidgetMovable && m_bLeftButtonTitlePressed) {
433:             if (m_pWidget->isMaximized()) {
434:                 // 先求出窗口到鼠标的相对位置
435:                 QRect normalGeometry = m_pWidget->normalGeometry();
436:                 m_pWidget->showNormal();
437:                 // 修改前：
438:                 // p.ry() -= 10;
439:                 // p.rx() -= (normalGeometry.width() / 2);
440: 
441:                 // 修改后：使用DPI缩放偏移量
442:                 qreal dpiScale = SAFramelessHelper::getScreenDpiScale(m_pWidget);
443:                 globalpos.ry() -= 10 * dpiScale;  // 缩放偏移量
444:                 globalpos.rx() -= (normalGeometry.width() / 2);
445: 
446:                 m_pWidget->move(globalpos);
447:                 // 这时要重置m_ptDragPos
448:                 m_ptDragPos = QPoint(normalGeometry.width() / 2, 10);
449:                 return (true);
450:             }
451: 
452:             bool isOutScreen          = true;
453:             QList< QScreen* > screens = QGuiApplication::screens();
454:             for (int i = 0; i < screens.size(); i++) {
455:                 QScreen* pScreen   = screens[ i ];
456:                 QRect geometryRect = pScreen->availableGeometry();
457:                 if (geometryRect.contains(globalpos)) {
458:                     isOutScreen = false;
459:                     break;
460:                 }
461:             }
462:             if (isOutScreen) {
463:                 event->ignore();
464:                 return false;
465:             }
466:             moveWidget(globalpos);
467:             return (true);
468:         }
469:         return (false);
470:     } else if (d->m_bWidgetResizable) {
471:         updateCursorShape(globalpos);
472:     }
473:     return (false);
474: }
