501:         if (m_pWidget) {
502:             SARibbonMainWindow* mainwindow = qobject_cast< SARibbonMainWindow* >(m_pWidget);
503:             if (mainwindow) {
504:                 if (mainwindow->windowFlags() & Qt::WindowMaximizeButtonHint) {
505:                     // 在最大化按钮显示时才进行shownormal处理
506: 
507:                     // 修改后：考虑DPI缩放
508:                     qreal dpiScale        = SAFramelessHelper::getScreenDpiScale(m_pWidget);
509:                     int scaledTitleHeight = SAPrivateFramelessCursorPosCalculator::s_titleHeight * dpiScale;
510:                     bool titlePressed     = SA::compat::eventPosY(event) < scaledTitleHeight;
511: 
512:                     if (titlePressed) {
513:                         if (m_pWidget->isMaximized()) {
514:                             m_pWidget->showNormal();
515:                         } else {
516:                             m_pWidget->showMaximized();
517:                         }
518:                         return (true);
519:                     }
520:                 }
521:             }
522:         }
523:     }
524:     return (false);
525: }
