553: bool SAFramelessHelper::eventFilter(QObject* obj, QEvent* event)
554: {
555:     switch (event->type()) {
556:     case QEvent::MouseMove:
557:     case QEvent::HoverMove:
558:     case QEvent::MouseButtonPress:
559:     case QEvent::MouseButtonRelease:
560:     case QEvent::MouseButtonDblClick:
561:     case QEvent::Leave: {
562:         if (d_ptr->m_widgetData) {
